'use strict';

const assert = require('assert');
const Base = require('sdk-base');
const sleep = require('mz-modules/sleep');
const utils = require('./utils');
const DiskStore = require('./disk_store');
const PollingRequest = require('./polling_request');

const CHECKSUM_NO_DATA = 'N';
const DEFAUT_OPTIONS = {
  responseTimeout: 500,
  pollingInterval: 30 * 1000, // 30s
};

class AntvipClient extends Base {
  constructor(options = {}) {
    assert(options.appName, '[AntvipClient] options.appName is required');
    assert(options.logger, '[AntvipClient] options.logger is required');
    assert(options.endpoint, '[AntvipClient] options.endpoint is required');
    assert(options.httpclient, '[AntvipClient] options.httpclient is required');
    super(Object.assign({}, DEFAUT_OPTIONS, options, { initMethod: '_init' }));

    this.url = `http://${this.options.endpoint}:9003/antcloud/antvip/instances/get`;
    this._diskStore = new DiskStore(options);
    this._isRunning = false;
    this._errorTime = 0;
    this._resolvedVipDomains = new Map(); // <domain>=<VipDomain>
    // ready 后开始定时轮询
    this.once('ready', this._scheduleSendRequest.bind(this));
  }

  get logger() {
    return this.options.logger;
  }

  get httpclient() {
    return this.options.httpclient;
  }

  get responseTimeout() {
    return this.options.responseTimeout;
  }

  /**
   * 订阅
   *
   * @param {String} name 名字
   * @param {Function} listener - 监听函数
   */
  subscribe(name, listener) {
    const vipDomain = this._resolvedVipDomains.get(name);
    if (vipDomain) {
      setImmediate(() => { listener(vipDomain); });
    } else {
      this._getVipDomain(name).catch(err => {
        // 这样轮询的时候会补偿
        this._resolvedVipDomains.set(name, null);
        this.emit('error', err);
      });
    }
    this.on(`vipdomain#${name}`, listener);
  }

  /**
   * 去订阅
   *
   * @param {String} name 名字
   * @param {Function} listener - 监听函数
   */
  unSubscribe(name, listener) {
    const key = `vipdomain#${name}`;
    if (listener) {
      this.removeListener(key, listener);
    } else {
      this.removeAllListeners(key);
    }
  }

  async _init() {
    this._isRunning = true;
    await this._diskStore.ready();
    await this._loadResolvedVipDomains();
    this.emit('ready');
  }

  async _scheduleSendRequest() {
    // 启动以后先等一个周期以后，开始轮询
    await sleep(this.options.pollingInterval);

    while (this._isRunning) {
      const pollingRequest = new PollingRequest({
        extensionParams: {
          appName: this.options.appName,
          checksumNewVersionSign: true,
          EXTENSION_ZONE_INFO_LIST: null,
        },
        accessKey: this.options.accessKey,
        accessSecret: this.options.accessSecret,
        instanceId: this.options.instanceId,
        vipDomainName2ChecksumMap: utils.buildVipDomainName2ChecksumMap(this._resolvedVipDomains),
        startTime: Date.now(),
      });
      try {
        const res = await this._request(pollingRequest);
        await this._handleResponse(res);
        this._errorTime = 0;
      } catch (err) {
        err.pollingRequest = pollingRequest.toString();
        this._errorTime++;
        // 连续错误三次，才抛错
        if (this._errorTime < 3) {
          this.logger.warn(err);
        } else {
          this.emit('error', err);
          // 重置
          this._errorTime = 0;
        }
      }
      // 间隔一段时间
      await sleep(this.options.pollingInterval);
    }
  }

  async _handleResponse(res) {
    // 检查响应是否成功，若不成功，抛出 AntVipResponseError 异常
    if (res.errorCode !== 0) {
      const err = new Error(`${res.errorMsg}(errorCode:${res.errorCode})`);
      err.name = 'AntVipResponseError';
      throw err;
    }

    // 域名
    if (res.vipDomains) {
      const vipDomains = res.vipDomains;
      // 先缓存到本地
      await this._diskStore.storeVipDomains(vipDomains);

      // 再更新内存并发事件通知
      for (const vipDomain of vipDomains) {
        this._resolvedVipDomains.set(vipDomain.name, vipDomain);
        this.emit(`vipdomain#${vipDomain.name}`, vipDomain);
      }
    }
  }

  async _request(pollingRequest) {
    const res = await this.httpclient.request(this.url, {
      method: 'POST',
      data: JSON.stringify(pollingRequest),
      dataType: 'text',
      timeout: pollingRequest.requestTimeLimitMS + 1000,
    });

    if (res.status !== 200) {
      const err = new Error(`get vip domain name list failed, statusCode=${res.status}`);
      err.name = 'AntvipPollingRequestError';
      err.pollingRequest = pollingRequest;
      throw err;
    }
    return JSON.parse(res.data);
  }

  async _loadResolvedVipDomains() {
    const vipDomains = await this._diskStore.loadVipDomains();
    if (vipDomains.length) {
      for (const vipDomain of vipDomains) {
        // weight 相关逻辑在 apiClient 里去做
        this._resolvedVipDomains.set(vipDomain.name, vipDomain);
      }
    }
  }

  async _getVipDomain(domainName) {
    assert(domainName, '[AntvipClient] _getVipDomain(domainName) domainName is required');
    const pollingRequest = new PollingRequest({
      allowPolling: false,
      vipDomainName2ChecksumMap: {
        [domainName]: CHECKSUM_NO_DATA,
      },
      requestTimeLimitMS: this.responseTimeout,
      startTime: Date.now(),
    });
    const res = await this._request(pollingRequest);
    this.logger.info('[AntvipClient] get vip domains: %j', res.vipDomains);

    if (res.vipDomains) {
      await this._handleResponse(res);
    } else {
      this.emit(`vipdomain#${domainName}`, null);
    }
  }

  close() {
    this._isRunning = false;
    this.emit('close');
    return Promise.resolve();
  }
}

module.exports = AntvipClient;
